        expect(await cdp.getProfile({ anonymousId: id })).toBeNull();
      }
      expect([...kv.store].filter(([k]) => k.startsWith('t:harbor:'))).toEqual(bBefore);
      for (const id of a.ids) { expect(d.object.open(shopperObjectName(a.tenant, id)).data.size).toBe(0); expect(d.ring.open(a.tenant + ':' + id).data.size).toBe(0); }
      for (const id of b.ids) { expect(d.object.open(shopperObjectName(b.tenant, id)).data.size).toBe(1); expect(d.ring.open(b.tenant + ':' + id).data.size).toBe(1); }
      const r2 = env.STORAGE as unknown as FakeR2, key = await erasureJobKey(a.tenant, a.selector), compact = JSON.parse(r2.store.get(key)!);
      expect(compact).toMatchObject({ version: 3, state: 'local_complete' }); expect(compact).not.toHaveProperty('targets'); expect(compact).not.toHaveProperty('selector'); expect(compact).not.toHaveProperty('sessions'); expect(compact).not.toHaveProperty('cacheKeys'); expect(compact).not.toHaveProperty('base');
      for (const id of [...a.ids, ...a.own, a.sid]) expect(r2.store.get(key)).not.toContain(id);
